import {runScenario,filterRaces} from '/core.mjs';

const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const pct=v=>Number.isFinite(v)?`${Math.round(v*100)}%`:'—';
const pct1=v=>Number.isFinite(v)?`${(v*100).toFixed(1)}%`:'—';
const signed=v=>Number.isFinite(v)?`${v>=0?'D +':'R +'}${Math.abs(v).toFixed(1)}`:'—';
const pp=v=>Number.isFinite(v)?`${v>0?'+':''}${(v*100).toFixed(1)} pp`:'—';
const fmt=v=>Number.isFinite(v)?Number(v).toFixed(1):'—';
const q=(s,r=document)=>r.querySelector(s), qa=(s,r=document)=>[...r.querySelectorAll(s)];
const routeView=()=>new URLSearchParams(location.search).get('view')||((location.pathname.split('/').filter(Boolean)[0])?'detail':'home');
const safeUrl=value=>{try{const u=new URL(value);return ['http:','https:'].includes(u.protocol)?u.href:null}catch{return null}};

let modelPromise=null,historyIndexPromise=null,raceSeriesPromise=null;
const model=()=>modelPromise??=fetch('/data/forecast.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw new Error(`forecast ${r.status}`);return r.json()});
const historyIndex=()=>historyIndexPromise??=fetch('/data/history/index.json',{cache:'no-store'}).then(r=>r.ok?r.json():({snapshots:[],summaries:[]})).catch(()=>({snapshots:[],summaries:[]}));
const raceSeries=()=>raceSeriesPromise??=fetch('/data/history/race-series.json',{cache:'no-store'}).then(r=>r.ok?r.json():({races:{}})).catch(()=>({races:{}}));

function stateLabel(code){return ({AL:'Alabama',AK:'Alaska',AZ:'Arizona',AR:'Arkansas',CA:'California',CO:'Colorado',CT:'Connecticut',DE:'Delaware',FL:'Florida',GA:'Georgia',HI:'Hawaii',ID:'Idaho',IL:'Illinois',IN:'Indiana',IA:'Iowa',KS:'Kansas',KY:'Kentucky',LA:'Louisiana',ME:'Maine',MD:'Maryland',MA:'Massachusetts',MI:'Michigan',MN:'Minnesota',MS:'Mississippi',MO:'Missouri',MT:'Montana',NE:'Nebraska',NV:'Nevada',NH:'New Hampshire',NJ:'New Jersey',NM:'New Mexico',NY:'New York',NC:'North Carolina',ND:'North Dakota',OH:'Ohio',OK:'Oklahoma',OR:'Oregon',PA:'Pennsylvania',RI:'Rhode Island',SC:'South Carolina',SD:'South Dakota',TN:'Tennessee',TX:'Texas',UT:'Utah',VT:'Vermont',VA:'Virginia',WA:'Washington',WV:'West Virginia',WI:'Wisconsin',WY:'Wyoming'})[code]||code}
function uncertainty(r){return Math.abs((r.dem_probability??.5)-.5)}
function winner(r){return (r.dem_probability??.5)>=.5?'D':'R'}
function winp(r){const p=r.dem_probability??.5;return Math.max(p,1-p)}
function externalEntries(r){return Object.entries(r.external_forecasters||{}).filter(([,x])=>x&&(x.rating||Number.isFinite(x.probability)))}
function ratingSide(text){const s=String(text||'').toLowerCase();if(/\b(d|dem|democratic)\b/.test(s))return'D';if(/\b(r|rep|republican)\b/.test(s))return'R';return null}
function disagreement(r){const ext=externalEntries(r),side=winner(r);if(!ext.length)return null;const opposed=ext.filter(([,x])=>ratingSide(x.rating)&&ratingSide(x.rating)!==side).length;if(opposed>=Math.ceil(ext.length/2))return'major';if(opposed>0)return'mild';return'consensus'}

function navigateRace(code){location.href=`/?race=${encodeURIComponent(code)}`}

/* ------------------------------- MAP ---------------------------------- */
function movementAt(code,days,series,currentP){
  const pts=(series?.races?.[code]||[]).filter(x=>Number.isFinite(x.dem_probability)&&x.generated_at).slice().sort((a,b)=>String(a.generated_at).localeCompare(String(b.generated_at)));
  if(!pts.length)return null;
  const now=new Date((pts.at(-1)?.generated_at)||Date.now()).valueOf();
  if(days==='previous'){
    const prev=pts.length>1?pts.at(-2):null;return prev?currentP-prev.dem_probability:null;
  }
  const target=now-Number(days)*86400000;
  let best=null,bestDist=Infinity;
  for(const p of pts){const t=new Date(p.generated_at).valueOf();if(t>now)continue;const d=Math.abs(t-target);if(d<bestDist){best=p;bestDist=d}}
  return best?currentP-best.dem_probability:null;
}
function mapValue(r,layer,delta=null){
  const p=r.dem_probability??.5,side=p>=.5?'D':'R',winnerP=Math.max(p,1-p),d=Number.isFinite(delta)?delta:(r.change?.dem_probability??0);
  if(layer==='margin')return {headline:signed(r.forecast_margin_d_minus_r),detail:`${pct(winnerP)} ${side} win`};
  if(layer==='movement')return {headline:Number.isFinite(d)?(Math.abs(d)<.00005?'No change':`${d>0?'D':'R'} ${Math.abs(d*100).toFixed(1)} pp`):'Unavailable',detail:`now ${pct(winnerP)} ${side}`};
  if(layer==='rating')return {headline:r.rating||'Unrated',detail:`${pct(winnerP)} ${side} win`};
  return {headline:`${pct(winnerP)} ${side}`,detail:r.rating||'Unrated'};
}
async function enhanceMap(){
  const grid=q('#mapGrid'),layerSel=q('#mapLayer'),chamberSel=q('#mapChamber');
  if(!grid||!layerSel||!chamberSel||grid.closest('[data-v1-map-ready]'))return;
  grid.closest('.panel')?.setAttribute('data-v1-map-ready','true');
  const data=await model();
  const toolbar=layerSel.closest('.toolbar');
  let period=q('#mapPeriod');
  if(!period){period=document.createElement('select');period.id='mapPeriod';period.setAttribute('aria-label','Movement comparison period');period.innerHTML='<option value="previous">Change since previous</option><option value="7">Change since 7 days</option><option value="30">Change since 30 days</option>';const requested=new URLSearchParams(location.search).get('period');if(requested)period.value=requested;layerSel.after(period)}
  let series=null;
  const render=async()=>{
    let rows=(data.races||[]).filter(r=>r.race_type===chamberSel.value).sort((a,b)=>String(a.state).localeCompare(String(b.state))||String(a.district||'').localeCompare(String(b.district||''),undefined,{numeric:true}));
    if(grid.dataset.competitive==='true')rows=rows.filter(r=>(r.dem_probability??.5)>=.2&&(r.dem_probability??.5)<=.8);
    const layer=layerSel.value;period.disabled=layer!=='movement';
    if(layer==='movement'&&!series)series=await raceSeries();
    grid.innerHTML=rows.map(r=>{const p=r.dem_probability??.5,side=p>=.5?'D':'R',cls=p>=.45&&p<=.55?'toss':side==='D'?'d-edge':'r-edge',delta=layer==='movement'?movementAt(r.race_code,period.value,series,p):null,v=mapValue(r,layer,delta);return `<button class="race-tile ${cls}" type="button" data-v1-race="${esc(r.race_code)}" aria-label="${esc(r.race_code)}, ${esc(v.headline)}, ${esc(v.detail)}"><span class="symbol">${esc(r.race_code)} · ${esc(v.headline)}</span><small>${esc(v.detail)}</small></button>`}).join('');
  };
  layerSel.addEventListener('change',()=>{const u=new URL(location.href);u.searchParams.set('layer',layerSel.value);history.replaceState(null,'',u);render()});
  period.addEventListener('change',()=>{const u=new URL(location.href);u.searchParams.set('period',period.value);history.replaceState(null,'',u);render()});
  grid.addEventListener('click',e=>{const b=e.target.closest('[data-v1-race]');if(b)navigateRace(b.dataset.v1Race)});
  const comp=q('#mapCompetitive');
  comp?.addEventListener('click',()=>{grid.dataset.competitive=grid.dataset.competitive==='true'?'false':'true';comp.textContent=grid.dataset.competitive==='true'?'Show all races':'Competitive only';setTimeout(render,0)});
  await render();
}

/* -------------------------- RACE EXPLORER ----------------------------- */
function explorerExternal(r){const ext=externalEntries(r);if(!ext.length)return'—';return ext.map(([name,x])=>`${name.replace('Political Report','').replace('Decision Desk HQ','DDHQ')}: ${x.rating??pct(x.probability)}`).join(' · ')}
function explorerRow(r){const delta=r.change?.dem_probability??0,last=r.latest_race_poll||'—',poll=r.poll_average_margin==null?'—':signed(r.poll_average_margin),base=Number.isFinite(r.relative_partisan_lean_d_minus_r)?signed(r.relative_partisan_lean_d_minus_r):'—',disc=disagreement(r);return `<div class="explorer-row" data-race-code="${esc(r.race_code)}"><div data-label="Race"><button type="button" class="text-link" data-v1-race="${esc(r.race_code)}"><strong>${esc(r.race_code)}</strong></button><small>${esc(stateLabel(r.state))}${r.open_seat?' · open':' '}</small></div><div data-label="Democrat">${esc(r.dem_candidate||'—')}</div><div data-label="Republican">${esc(r.rep_candidate||'—')}</div><div data-label="Model"><strong class="${winner(r)==='D'?'lead-d':'lead-r'}">${pct(winp(r))} ${winner(r)}</strong><small>${pct(r.dem_probability)} D</small></div><div data-label="Expected margin">${esc(signed(r.forecast_margin_d_minus_r))}</div><div data-label="Poll average">${esc(poll)}</div><div data-label="Baseline">${esc(base)}</div><div data-label="Rating">${esc(r.rating||'—')}</div><div data-label="Movement"><span class="movement ${delta>0?'lead-d':delta<0?'lead-r':''}">${Math.abs(delta)<.00005?'—':pp(delta)}</span></div><div data-label="Last poll">${esc(last)}</div><div data-label="External"><span class="${disc==='major'?'disagree-major':''}">${esc(explorerExternal(r))}</span></div></div>`}
function sortExplorer(rows,sort){const r=[...rows];if(sort==='dprob')return r.sort((a,b)=>(b.dem_probability??0)-(a.dem_probability??0));if(sort==='rprob')return r.sort((a,b)=>(a.dem_probability??0)-(b.dem_probability??0));if(sort==='movement')return r.sort((a,b)=>Math.abs(b.change?.dem_probability||0)-Math.abs(a.change?.dem_probability||0));if(sort==='margin')return r.sort((a,b)=>Math.abs(a.forecast_margin_d_minus_r||0)-Math.abs(b.forecast_margin_d_minus_r||0));if(sort==='polls')return r.sort((a,b)=>(b.poll_count||0)-(a.poll_count||0));if(sort==='baseline')return r.sort((a,b)=>Math.abs(a.relative_partisan_lean_d_minus_r||0)-Math.abs(b.relative_partisan_lean_d_minus_r||0));return r.sort((a,b)=>uncertainty(a)-uncertainty(b))}
async function enhanceExplorer(){
  const results=q('#raceResults'),toolbar=q('#moreFilters');if(!results||!toolbar||q('#explorerV1'))return;
  const data=await model(),p=new URLSearchParams(location.search),extConfigured=(data.external_forecasters?.configured_count||0)>0,moneyConfigured=data.money?.state==='current';
  const extras=document.createElement('section');extras.id='explorerV1';extras.className='explorer-tools';extras.innerHTML=`<div class="preset-row explorer-presets" aria-label="Race Explorer presets"><button type="button" data-v1-preset="tossup">TOSS-UPS</button><button type="button" data-v1-preset="flip">MOST LIKELY FLIPS</button><button type="button" data-v1-preset="uncertain">MOST UNCERTAIN</button><button type="button" data-v1-preset="movers">BIGGEST MOVERS</button><button type="button" data-v1-preset="unpolled">UNPOLLED BATTLEGROUNDS</button><button type="button" data-v1-preset="disagreement" ${extConfigured?'':'disabled title="No licensed external-forecaster feed configured"'}>MODEL / EXPERT DISAGREEMENT</button></div><div class="toolbar explorer-extra"><select id="raceIncumbency" aria-label="Incumbency"><option value="all">Incumbent + open</option><option value="open">Open seats only</option><option value="incumbent">Incumbent seats only</option></select><select id="raceMovement" aria-label="Forecast movement"><option value="all">Any movement</option><option value="big">Moved ≥5 pp</option><option value="d">Moved toward D</option><option value="r">Moved toward R</option></select><select id="raceSeatMode" aria-label="Seat status"><option value="all">Any seat status</option><option value="flip">Model-favoured flips</option></select><select id="raceSort" aria-label="Sort races"><option value="competitive">Sort: closest first</option><option value="movement">Sort: biggest movers</option><option value="dprob">Sort: D probability</option><option value="rprob">Sort: R probability</option><option value="margin">Sort: closest margin</option><option value="polls">Sort: most polls</option><option value="baseline">Sort: closest baseline</option></select><select id="raceExternal" aria-label="External forecaster disagreement" ${extConfigured?'':'disabled'}><option value="all">${extConfigured?'Any expert status':'External ratings unavailable'}</option><option value="major">Major disagreement</option><option value="mild">Any disagreement</option></select><select id="raceMoney" aria-label="Fundraising filter" disabled><option>${moneyConfigured?'Money filter pending comparable periods':'FEC data unavailable'}</option></select></div><p class="data-note">External-rating and money filters activate only when permitted, comparable source data are present. Disabled controls are deliberate unavailable states, not missing UI.</p>`;
  toolbar.after(extras);
  for(const [id,key] of [['raceIncumbency','incumbency'],['raceMovement','movement'],['raceSeatMode','seatmode'],['raceSort','sort'],['raceExternal','external']]){const el=q(`#${id}`);if(el&&p.get(key))el.value=p.get(key)}
  const render=()=>{
    const f={query:q('#raceQ')?.value||'',chamber:q('#raceChamber')?.value||'all',state:q('#raceState')?.value||'all',party:q('#raceParty')?.value||'all',competitiveness:q('#raceComp')?.value||'all',polling:q('#racePolling')?.value||'all',minProb:Number(q('#minProb')?.value||0)/100,maxProb:Number(q('#maxProb')?.value||100)/100};
    let rows=filterRaces(data.races||[],f);const inc=q('#raceIncumbency').value,mv=q('#raceMovement').value,seat=q('#raceSeatMode').value,external=q('#raceExternal').value;
    rows=rows.filter(r=>{const d=r.change?.dem_probability||0;if(inc==='open'&&!r.open_seat)return false;if(inc==='incumbent'&&r.open_seat)return false;if(mv==='big'&&Math.abs(d)<.05)return false;if(mv==='d'&&d<=0)return false;if(mv==='r'&&d>=0)return false;if(seat==='flip'&&!((r.seat_holder==='REP'&&r.dem_probability>.5)||(r.seat_holder==='DEM'&&r.dem_probability<.5)))return false;const disc=disagreement(r);if(external==='major'&&disc!=='major')return false;if(external==='mild'&&!['major','mild'].includes(disc))return false;return true});
    rows=sortExplorer(rows,q('#raceSort').value);
    results.innerHTML=`<div class="explorer-table"><div class="explorer-row explorer-head" aria-hidden="true"><div>RACE</div><div>DEMOCRAT</div><div>REPUBLICAN</div><div>MODEL</div><div>MARGIN</div><div>POLL AVG</div><div>BASELINE</div><div>RATING</div><div>MOVEMENT</div><div>LAST POLL</div><div>EXTERNAL</div></div>${rows.map(explorerRow).join('')}</div>`;
    const summary=q('#filterSummary');if(summary)summary.textContent=`${rows.length} of ${data.races.length} races shown · sorted ${q('#raceSort').selectedOptions[0].textContent.replace('Sort: ','').toLowerCase()}.`;
    const u=new URL(location.href);u.searchParams.set('view','races');for(const [key,val,def] of [['incumbency',inc,'all'],['movement',mv,'all'],['seatmode',seat,'all'],['sort',q('#raceSort').value,'competitive'],['external',external,'all']]){if(val!==def)u.searchParams.set(key,val);else u.searchParams.delete(key)}history.replaceState(null,'',u);
  };
  const controls=[...qa('#raceToolbar input,#raceToolbar select,#moreFilters input,#moreFilters select,#explorerV1 select')];controls.forEach(el=>el.addEventListener(el.tagName==='INPUT'?'input':'change',()=>queueMicrotask(render)));
  extras.addEventListener('click',e=>{const b=e.target.closest('[data-v1-preset]');if(!b)return;const preset=b.dataset.v1Preset;if(preset==='tossup')q('#raceComp').value='tossup';if(preset==='uncertain')q('#raceComp').value='uncertain';if(preset==='flip')q('#raceSeatMode').value='flip';if(preset==='movers'){q('#raceMovement').value='big';q('#raceSort').value='movement'}if(preset==='unpolled'){q('#raceComp').value='competitive';q('#racePolling').value='none'}if(preset==='disagreement'&&extConfigured)q('#raceExternal').value='mild';render()});
  results.addEventListener('click',e=>{const b=e.target.closest('[data-v1-race]');if(b)navigateRace(b.dataset.v1Race)});
  render();
}

/* ---------------------------- POLLING --------------------------------- */
function allPolls(data){const out=[];for(const p of (data.polls||data.national_environment?.recent_polls||[]))out.push({...p,scope:'National',race_type:'national'});for(const r of data.races||[])for(const p of r.polls||[])out.push({...p,scope:r.race_code,race_type:r.race_type});const seen=new Set();return out.filter(p=>{const k=[p.scope,p.pollster,p.start_date,p.end_date,p.dem,p.rep,p.sponsor].join('|');if(seen.has(k))return false;seen.add(k);return true}).sort((a,b)=>String(b.end_date||'').localeCompare(String(a.end_date||'')))}
function pollCard(p){const src=safeUrl(p.source),sponsor=p.sponsor?`${p.sponsor}${p.sponsor_lean?` · ${p.sponsor_lean}-lean`:''}`:'No sponsor recorded';return `<article class="poll-card"><div><button class="text-link pollster-link" type="button" data-v1-pollster="${esc(p.pollster)}"><strong>${esc(p.pollster||'Unknown pollster')}</strong></button><small>${esc(p.scope||'National')} · ${esc(p.start_date||'—')}–${esc(p.end_date||'—')}</small></div><div><b>${esc(signed(p.margin))}</b><small>D ${p.dem??'—'} · R ${p.rep??'—'}</small></div><div><b>${p.n?Number(p.n).toLocaleString():'—'}</b><small>${esc(p.population||'sample unspecified')} · ${esc(p.mode||'mode unspecified')}</small></div><div><small>${esc(sponsor)}</small>${src?`<a href="${esc(src)}" target="_blank" rel="noopener noreferrer">Source ↗</a>`:''}</div></article>`}
async function enhancePolling(){
  if(routeView()!=='polls'||q('#pollDatabase'))return;const data=await model(),polls=allPolls(data);const host=q('#content');if(!host)return;
  const pollsters=[...new Set(polls.map(p=>p.pollster).filter(Boolean))].sort();
  const section=document.createElement('section');section.id='pollDatabase';section.className='section panel panel-pad';section.innerHTML=`<div class="section-head"><div><div class="eyebrow">POLL DATABASE</div><h2>${polls.length} current-window observations</h2><p>Search raw national and race polls without changing the official aggregate or forecast.</p></div></div><div class="poll-db-controls"><input id="pollDbQ" type="search" placeholder="Pollster, race or sponsor" aria-label="Search poll database"><select id="pollDbScope" aria-label="Poll scope"><option value="all">National + House + Senate</option><option value="national">National generic ballot</option><option value="house">House races</option><option value="senate">Senate races</option></select><select id="pollDbPollster" aria-label="Pollster"><option value="all">All pollsters</option>${pollsters.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')}</select><select id="pollDbSponsor" aria-label="Sponsorship"><option value="all">Any sponsorship</option><option value="nonpartisan">No partisan lean recorded</option><option value="partisan">Partisan sponsor recorded</option></select></div><div id="pollDbSummary" class="filter-summary"></div><div id="pollDbRows" class="poll-cards"></div>`;host.append(section);
  const render=()=>{const text=q('#pollDbQ').value.trim().toLowerCase(),scope=q('#pollDbScope').value,pollster=q('#pollDbPollster').value,sponsor=q('#pollDbSponsor').value;const rows=polls.filter(p=>{if(scope!=='all'&&p.race_type!==scope)return false;if(pollster!=='all'&&p.pollster!==pollster)return false;if(sponsor==='partisan'&&!p.sponsor_lean)return false;if(sponsor==='nonpartisan'&&p.sponsor_lean)return false;if(text&&!`${p.pollster} ${p.scope} ${p.sponsor||''}`.toLowerCase().includes(text))return false;return true});q('#pollDbSummary').textContent=`${rows.length} of ${polls.length} observations shown.`;q('#pollDbRows').innerHTML=rows.length?rows.slice(0,180).map(pollCard).join(''):'<div class="empty-state">No poll observations match these filters.</div>'};
  qa('#pollDatabase input,#pollDatabase select').forEach(x=>x.addEventListener(x.tagName==='INPUT'?'input':'change',render));section.addEventListener('click',e=>{const b=e.target.closest('[data-v1-pollster]');if(b)location.href=`/?pollster=${encodeURIComponent(b.dataset.v1Pollster)}`});render();
}
async function enhancePollster(){
  const isPollster=location.pathname.startsWith('/pollsters/')||new URLSearchParams(location.search).has('pollster');if(!isPollster||q('#pollsterAllRecords'))return;const data=await model(),label=q('.page-head h1')?.textContent?.trim();if(!label)return;const rows=allPolls(data).filter(p=>String(p.pollster||'').toLowerCase()===label.toLowerCase());const host=q('#content');if(!host)return;const section=document.createElement('section');section.id='pollsterAllRecords';section.className='section panel panel-pad';section.innerHTML=`<div class="eyebrow">ALL CURRENT-CYCLE RECORDS</div><h2>${rows.length} observations across national and race polling</h2>${rows.length?`<div class="poll-cards">${rows.map(pollCard).join('')}</div>`:'<div class="empty-state">No current-cycle records are present for this pollster.</div>'}`;host.append(section);
}

/* ------------------------------ HISTORY ------------------------------- */
function compactDelta(a,b,key){const x=a?.[key],y=b?.[key];return Number.isFinite(x)&&Number.isFinite(y)?x-y:null}
function historyPreview(row,current){if(!row)return'<div class="empty-state">No snapshot selected.</div>';const dh=compactDelta(row,current,'house'),ds=compactDelta(row,current,'senate'),dhs=compactDelta(row,current,'house_seats'),dg=compactDelta(row,current,'generic_ballot_d_minus_r');return `<div class="history-preview"><div><small>Snapshot</small><strong>${esc(new Date(row.generated_at).toLocaleString())}</strong></div><div><small>House D control</small><strong>${pct(row.house)}</strong><span>${Number.isFinite(dh)?`${pp(dh)} vs selected baseline`:''}</span></div><div><small>Senate D control</small><strong>${pct(row.senate)}</strong><span>${Number.isFinite(ds)?`${pp(ds)} vs selected baseline`:''}</span></div><div><small>Expected D House seats</small><strong>${fmt(row.house_seats)}</strong><span>${Number.isFinite(dhs)?`${dhs>0?'+':''}${dhs.toFixed(1)} seats`:''}</span></div><div><small>Generic ballot</small><strong>${signed(row.generic_ballot_d_minus_r)}</strong><span>${Number.isFinite(dg)?`${dg>0?'+':''}${dg.toFixed(1)} pts`:''}</span></div></div>`}
async function enhanceHistory(){
  const list=q('.history-list');if(!list||q('#historyWorkbench'))return;const idx=await historyIndex(),rows=(idx.summaries||[]).length?idx.summaries:((await model()).history_summaries||[]);if(!rows.length)return;
  const panel=list.closest('.panel'),work=document.createElement('section');work.id='historyWorkbench';work.className='history-workbench';const latest=rows[0];work.innerHTML=`<div class="history-controls"><label>Snapshot scrubber <input id="historySlider" type="range" min="0" max="${Math.max(0,rows.length-1)}" value="0" step="1"></label><button type="button" id="historyPlay" class="button secondary">Play</button><label>Compare with <select id="historyCompare"><option value="1">previous snapshot</option><option value="7">about 7 days earlier</option><option value="30">about 30 days earlier</option><option value="first">first indexed forecast</option></select></label><button type="button" id="historyOpen" class="button secondary">Open selected full snapshot</button></div><div id="historyPreview">${historyPreview(latest,latest)}</div><div id="historyCompareOut"></div>`;panel?.prepend(work);
  const slider=q('#historySlider'),preview=q('#historyPreview'),compareOut=q('#historyCompareOut');let timer=null;
  const selected=()=>rows[Math.min(rows.length-1,Number(slider.value)||0)];
  const nearestDays=(anchor,days)=>{const target=new Date(anchor.generated_at).valueOf()-days*86400000;return rows.reduce((best,x)=>Math.abs(new Date(x.generated_at).valueOf()-target)<Math.abs(new Date(best.generated_at).valueOf()-target)?x:best,rows.at(-1))};
  const render=()=>{const a=selected();preview.innerHTML=historyPreview(a,a);const v=q('#historyCompare').value;let b=v==='first'?rows.at(-1):nearestDays(a,Number(v));compareOut.innerHTML=`<div class="eyebrow">COMPARISON</div>${historyPreview(a,b)}<p class="data-note">Differences are arithmetic comparisons of archived outputs. Causation is shown only where the snapshot’s changed-input metadata identifies changed inputs.</p>`};
  slider.addEventListener('input',render);q('#historyCompare').addEventListener('change',render);q('#historyPlay').addEventListener('click',()=>{if(timer){clearInterval(timer);timer=null;q('#historyPlay').textContent='Play';return}if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;slider.value=String(rows.length-1);render();q('#historyPlay').textContent='Pause';timer=setInterval(()=>{const n=Number(slider.value)-1;if(n<0){clearInterval(timer);timer=null;q('#historyPlay').textContent='Play';return}slider.value=String(n);render()},850)});
  q('#historyOpen').addEventListener('click',()=>openSnapshot(selected()?.file));
  list.addEventListener('click',e=>{const b=e.target.closest('[data-history-file]');if(b)openSnapshot(b.dataset.historyFile,b)});render();
}
async function openSnapshot(file,button=null){if(!file)return;button?.setAttribute('aria-busy','true');try{const snap=await fetch(`/data/history/${encodeURIComponent(file)}`,{cache:'no-store'}).then(r=>{if(!r.ok)throw new Error(r.status);return r.json()});let detail=q('#snapshotDetail');if(!detail){detail=document.createElement('section');detail.id='snapshotDetail';detail.className='section panel panel-pad';q('.history-list')?.closest('.panel')?.after(detail)}const h=snap.summary?.house||{},s=snap.summary?.senate||{},g=snap.national_environment?.generic_ballot_d_minus_r;const close=(snap.races||[]).slice().sort((a,b)=>uncertainty(a)-uncertainty(b)).slice(0,8);detail.innerHTML=`<div class="eyebrow">SELECTED IMMUTABLE SNAPSHOT</div><h2>${esc(new Date(snap.generated_at).toLocaleString())}</h2><div class="facts-grid"><div class="fact"><b>${pct(h.dem_control_probability)}</b><span>House D control</span></div><div class="fact"><b>${fmt(h.expected_dem_seats)}</b><span>expected D House seats</span></div><div class="fact"><b>${pct(s.dem_control_probability)}</b><span>Senate D control</span></div><div class="fact"><b>${Number.isFinite(g)?signed(g):'—'}</b><span>generic ballot D−R</span></div></div><h3>Closest races then</h3><div class="race-grid">${close.map(r=>`<button class="race-tile ${winner(r)==='D'?'d-edge':'r-edge'}" type="button" data-v1-race="${esc(r.race_code)}"><span class="symbol">${esc(r.race_code)}</span><small>${pct(winp(r))} ${winner(r)}</small></button>`).join('')}</div><p class="data-note">Full immutable archived snapshot. It is not recomputed with today’s inputs or model state.</p>`;detail.onclick=e=>{const b=e.target.closest('[data-v1-race]');if(b)navigateRace(b.dataset.v1Race)};detail.scrollIntoView({block:'start'})}catch(err){console.error('snapshot',err)}finally{button?.removeAttribute('aria-busy')}}
async function enhanceRaceHistory(){
  const panels=qa('.section.panel'),panel=panels.find(x=>x.querySelector('.eyebrow')?.textContent.trim()==='PROBABILITY HISTORY');if(!panel||panel.dataset.compactHistory)return;panel.dataset.compactHistory='true';const code=new URLSearchParams(location.search).get('race')||decodeURIComponent(location.pathname.split('/').filter(Boolean)[1]||'');if(!code)return;const series=await raceSeries(),pts=series?.races?.[code]||series?.races?.[code.toUpperCase()]||[];if(!pts.length)return;const body=panel.querySelector('.empty-state,.timeline-list');if(body)body.outerHTML=`<div class="timeline-list">${pts.slice(-60).map(x=>`<div class="timeline"><small>${esc(new Date(x.generated_at).toLocaleDateString())}</small><div class="track" role="img" aria-label="Democratic win probability ${pct(x.dem_probability)}"><span style="width:${Math.max(0,Math.min(100,(x.dem_probability??.5)*100))}%"></span></div><strong>${pct(x.dem_probability)}</strong></div>`).join('')}</div><p class="data-note">Compact derivative timeline from immutable production snapshots. Full snapshots remain the source of truth.</p>`;
}

